"""Report assembly helpers: limitations, deterministic summary, status rules."""

from __future__ import annotations

from .schemas import (
    SPECIALISTS,
    AgentName,
    AgentRunStatus,
    AgentStatus,
    ConsensusAssessment,
    Disagreement,
    DisagreementStatus,
    ExecutiveSummary,
    Recommendation,
    ReportStatus,
    RoutingPlan,
)

STANDARD_LIMITATIONS = (
    "Analysis is based solely on the description provided; missing details lower confidence.",
    "Findings are generated by language models and can be incomplete or wrong. "
    "Review them with domain experts.",
    "Any reference to EU AI Act tiers or GDPR is a hypothesis to be confirmed by qualified "
    "legal review, not a classification.",
    "Agent weights and consensus thresholds are fixed heuristics, not calibrated statistics.",
)


def report_status(
    statuses: dict[AgentName, AgentRunStatus],
    routing: RoutingPlan | None,
    critic_failed: bool,
    has_results: bool,
) -> ReportStatus:
    if not has_results:
        return ReportStatus.FAILED
    selected = routing.selected() if routing else list(SPECIALISTS)
    specialist_failed = any(
        statuses.get(a) is not None and statuses[a].status is AgentStatus.FAILED for a in selected
    )
    orchestrator_failed = (
        statuses.get(AgentName.ORCHESTRATOR) is not None
        and statuses[AgentName.ORCHESTRATOR].status is AgentStatus.FAILED
    )
    if specialist_failed or critic_failed or orchestrator_failed:
        return ReportStatus.PARTIAL
    return ReportStatus.COMPLETE


def build_limitations(
    statuses: dict[AgentName, AgentRunStatus],
    routing: RoutingPlan | None,
    disagreements: list[Disagreement],
    critic_failed: bool,
    summary_mode: str,
    deadline_hit: bool,
) -> list[str]:
    out = list(STANDARD_LIMITATIONS)
    failed = [a.value for a, s in statuses.items() if s.status is AgentStatus.FAILED]
    if failed:
        out.append(
            "These agents failed and are missing from the analysis: "
            + ", ".join(sorted(failed))
            + ". The report is marked PARTIAL."
        )
    if (
        AgentName.ORCHESTRATOR in statuses
        and statuses[AgentName.ORCHESTRATOR].status is AgentStatus.FAILED
    ):
        out.append(
            "The orchestrator failed; all specialists ran with a deterministic fallback profile."
        )
    if critic_failed:
        out.append(
            "The critic review did not complete cleanly, so cross-agent checks rely on "
            "deterministic rules only."
        )
    if routing and routing.skipped():
        out.append(
            "Skipped by the orchestrator as not needed: "
            + ", ".join(a.value for a in routing.skipped())
            + ". See the routing justification."
        )
    notes = [s.note for s in statuses.values() if s.note and "retained" in s.note]
    if notes:
        out.append(
            "A targeted reassessment failed for at least one agent; its earlier "
            "assessment was retained."
        )
    if any(d.status is DisagreementStatus.UNRESOLVED for d in disagreements):
        out.append("Some disagreements between agents remain unresolved and are disclosed below.")
    if summary_mode == "DETERMINISTIC":
        out.append(
            "The executive summary was composed by code because the summary model "
            "step did not complete."
        )
    if deadline_hit:
        out.append("The run deadline was reached; some steps were not completed.")
    return out


def deterministic_summary(
    consensus: ConsensusAssessment,
    recommendations: list[Recommendation],
    disagreements: list[Disagreement],
    status: ReportStatus,
) -> ExecutiveSummary:
    top = recommendations[:3]
    unresolved = [d for d in disagreements if d.status is DisagreementStatus.UNRESOLVED]
    sentences = [
        f"Based on the provided description, the combined agent analysis indicates an overall "
        f"{consensus.overall_level.value} level with confidence "
        f"{consensus.overall_confidence:.2f}.",
        f"{len(consensus.entries)} specialist agent(s) contributed to this result.",
    ]
    if top:
        sentences.append("Highest-priority themes: " + "; ".join(r.title for r in top) + ".")
    if unresolved:
        sentences.append(f"{len(unresolved)} disagreement(s) between agents remain unresolved.")
    if status is not ReportStatus.COMPLETE:
        sentences.append("Part of the analysis did not complete, so treat the result as partial.")
    points = [r.title for r in top] or ["See agent findings for details."]
    return ExecutiveSummary(text=" ".join(sentences), key_points=points[:5])
